from PyQt5 import QtWidgets,uic

def verif(a,b):
    ok = b.isnumeric()
    i = -1
    while ok and i < len(a)-1 :
        i += 1
        if a[i].isnumeric():
            ok = int(a[i]) < int(b) 
        else :
            ok = int(b) > 9 and "A" <= a[i] <= chr(55+int(b))
    return ok
    
    
def base10(a,b):
    S = 0
    for i in range (len(a)):
        if a[i].isnumeric():
            S = S*int(b) + int(a[i])
        else :
            S = S*int(b) + ord(a[i])-55
    return str(S)
def traitement(a,b):
    if verif(a,b):
        p.t3.setText(base10(a,b))
    else:
        p.t3.setText("INPUT ERROR")

def effacer():
    p.t1.setText("")
    p.t2.setText("")
    p.t3.setText("")
    p.t1.setFocus()
    
app = QtWidgets.QApplication([])
p = uic.loadUi("conversion_dans_la_base_10.ui")
p.show()
p.pb1.clicked.connect(lambda:traitement(p.t1.text(),p.t2.text()))
p.pb2.clicked.connect(effacer)
app.exec_()

